import { createContext, useState } from "react";

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);

  const login = ({ role, email, password, pin }) => {
    // 🏛 Authority login check
    if (role === "authority") {
      if (
        email === "1234@gmail.com" &&
        password === "1234@1234" &&
        pin === "1234"
      ) {
        const authUser = { role: "authority", email };
        setUser(authUser);
        localStorage.setItem("user", JSON.stringify(authUser));
        return { success: true };
      } else {
        return { success: false, message: "Invalid authority credentials" };
      }
    }

    // 👤 Citizen login (no restriction)
    if (role === "citizen") {
      const citizenUser = { role: "citizen", email };
      setUser(citizenUser);
      localStorage.setItem("user", JSON.stringify(citizenUser));
      return { success: true };
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem("user");
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};
